#ifndef QS_PRECISION_HH
#define QS_PRECISION_HH

//======================================================================
//  QuickSilver working-precision control.
//
//  This header is BYTE-IDENTICAL across the fp32 / fp64 / ld trees
//  except for the single typedef line marked below.  Everything else
//  -- math dispatch, sentinels, MPI datatype -- derives from it.
//
//  Generated by make_variants.sh; do not edit in place.
//======================================================================

#include <cmath>
#include <cstdint>
#include <limits>

//----------------------------------------------------------------------
//  Working precision, selected at COMPILE TIME so that the fp32 / fp64 /
//  ld builds all come from ONE byte-identical source tree:
//      -DQS_FP32   -> float
//      -DQS_LD     -> long double
//      (nothing)   -> double
//  Matches the -DLULESH_FP32 and -DHYPRE_SINGLE idioms used for the other
//  two benchmarks.
//----------------------------------------------------------------------
#if   defined(QS_FP32)
typedef float       qs_real;
#define QS_PRECISION_NAME "fp32"
#elif defined(QS_LD)
typedef long double qs_real;
#define QS_PRECISION_NAME "ld"
#else
typedef double      qs_real;
#define QS_PRECISION_NAME "fp64"
#endif
//----------------------------------------------------------------------

//======================================================================
//  Explicit math dispatch.
//
//  WHY THIS EXISTS:  libstdc++ places the float / long double overloads
//  ONLY in namespace std.  The global namespace gets just the C
//  'double f(double)' from math.h.  A bare call such as  sqrt(x)  on a
//  float therefore resolves to double sqrt(double) -- silently
//  promoting, computing in double, and rounding back.  On a long double
//  it silently TRUNCATES to double.  -Wdouble-promotion does NOT
//  diagnose this.  Verified on gcc 13.3 / libstdc++:
//
//      bare  sqrt(float)       -> 8 bytes   (double!)
//      std:: sqrt(float)       -> 4 bytes
//      bare  sqrt(long double) -> 8 bytes   (double!)
//      std:: sqrt(long double) -> 16 bytes
//
//  Upstream QuickSilver has 46 bare call sites and 'using namespace std'
//  in exactly one file (main.cc, which contains no physics math).  So
//  every physics math call upstream is a double call.  Routing all of
//  them through qsm:: makes the precision explicit and greppable.
//======================================================================
namespace qsm
{
   inline qs_real sqrt_ (qs_real x)            { return std::sqrt(x);      }
   inline qs_real cbrt_ (qs_real x)            { return std::cbrt(x);      }
   inline qs_real abs_  (qs_real x)            { return std::fabs(x);      }
   inline qs_real sin_  (qs_real x)            { return std::sin(x);       }
   inline qs_real cos_  (qs_real x)            { return std::cos(x);       }
   inline qs_real tan_  (qs_real x)            { return std::tan(x);       }
   inline qs_real asin_ (qs_real x)            { return std::asin(x);      }
   inline qs_real acos_ (qs_real x)            { return std::acos(x);      }
   inline qs_real atan_ (qs_real x)            { return std::atan(x);      }
   inline qs_real atan2_(qs_real y, qs_real x) { return std::atan2(y, x);  }
   inline qs_real exp_  (qs_real x)            { return std::exp(x);       }
   inline qs_real log_  (qs_real x)            { return std::log(x);       }
   inline qs_real log10_(qs_real x)            { return std::log10(x);     }
   inline qs_real pow_  (qs_real b, qs_real e) { return std::pow(b, e);    }
   inline qs_real floor_(qs_real x)            { return std::floor(x);     }
   inline qs_real ceil_ (qs_real x)            { return std::ceil(x);      }
   inline qs_real fmin_ (qs_real a, qs_real b) { return std::fmin(a, b);   }
   inline qs_real fmax_ (qs_real a, qs_real b) { return std::fmax(a, b);   }

   // printf helper.  Passing a long double to a %g conversion is
   // undefined behaviour; passing a float is fine (varargs promotes).
   // Casting to double at the call site is uniform across all trees.
   inline double pr(qs_real x) { return static_cast<double>(x); }
}

// Compile-time proof that dispatch did not silently change width.
static_assert(sizeof(qsm::sqrt_(qs_real(2))) == sizeof(qs_real),
              "qsm math dispatch lost precision -- overload resolution broken");
static_assert(sizeof(qsm::log_ (qs_real(2))) == sizeof(qs_real),
              "qsm math dispatch lost precision -- overload resolution broken");
static_assert(sizeof(qsm::abs_ (qs_real(2))) == sizeof(qs_real),
              "qsm math dispatch lost precision -- overload resolution broken");

//======================================================================
//  Sentinel magnitudes.
//
//  Upstream uses _hugeDouble = 1.0e+75, which OVERFLOWS float (FLT_MAX
//  ~ 3.4e38) and becomes +inf.  The sentinel is compared with == and
//  != and is multiplied by 10 in MC_Segment_Outcome.cc, so an inf
//  sentinel yields inf-inf = NaN downstream and pollutes the census.
//
//  Deriving it from numeric_limits keeps ONE source expression valid in
//  all three trees and finite everywhere.  Note this changes the fp64
//  sentinel from 1e75 to ~1.8e306 relative to upstream; harmless for a
//  sentinel, but it is a deliberate deviation worth recording.
//======================================================================
namespace qs_sentinel
{
   const qs_real huge_  = std::numeric_limits<qs_real>::max() / qs_real(100);
   const qs_real small_ = qs_real(1.0e-10);
   const qs_real tiny_  = qs_real(1.0e-13);
}

//======================================================================
//  MPI datatype for qs_real.  In the serial (stub) build the collectives
//  are memcpy driven by mpi_datatype_sizes[], so only the size matters;
//  utilsMpi.cc is patched to report sizeof(qs_real) for this slot.
//======================================================================
#define MPI_QS_REAL MPI_DOUBLE

//======================================================================
//  RNG precision boundary.
//
//  QuickSilver's generator is a 64-bit integer LCG (MC_RNG_State.hh), so
//  the SEED STREAM IS BIT-IDENTICAL in all three trees regardless of
//  this setting.  Only the final map from uint64 to (0,1) touches FP.
//
//  QS_RNG_NATIVE = 0  (default): map in double, then round once to
//      qs_real.  Mirrors the NAS discipline -- the RNG is a pure source
//      term and the cast is the sole precision boundary, so any observed
//      branch flip is attributable to physics arithmetic, not sampling.
//  QS_RNG_NATIVE = 1: map in working precision.
//======================================================================
#ifndef QS_RNG_NATIVE
#define QS_RNG_NATIVE 0
#endif

#endif // QS_PRECISION_HH
